<?php
namespace App\Http\Requests;
use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule;
class ContentRequest extends FormRequest { public function authorize():bool{return (bool)$this->user()?->is_admin;} public function rules():array{return ['type'=>['required',Rule::in(['page','service','service_category','solution','industry','project','testimonial','faq','partner'])],'title'=>['required','string','max:180'],'slug'=>['required','alpha_dash','max:180',Rule::unique('contents')->where('type',$this->input('type'))->ignore($this->route('content'))],'summary'=>['nullable','string','max:1000'],'content'=>['nullable','string'],'status'=>['required',Rule::in(['draft','published','archived'])],'sort_order'=>['integer','min:0'],'is_featured'=>['boolean'],'published_at'=>['nullable','date'],'featured_image'=>['nullable','image','mimes:jpg,jpeg,png,webp,avif','max:4096'],'meta_title'=>['nullable','string','max:70'],'meta_description'=>['nullable','string','max:170']];} }
